    trapPhase = TRAP_RAMP_UP;
    trapStartMs = 0;
    vescWatchActive = true;
    lastVescWatchMs = 0;
    g_mock_millis = VESC_WATCH_PERIOD_MS + 1;   // period elapsed — would poll if not suppressed
    g_mock_micros = 1000000;
